  'Writing & Content': ['writing', 'blog', 'content', 'author', 'book', 'novel', 'story', 'poet', 'write', 'writer', 'publish', 'journal', 'grammar', 'language', 'editor', 'proofread', 'manuscript', 'draft', 'revision', 'edit', 'storytelling', 'narrative', 'fiction', 'nonfiction', 'article', 'essay', 'copywriting'],
