};

// Apply categorization to all bookmarks
const categorizedBookmarks = uniqueBookmarks.map(bookmark => {
  let assigned = false;
  let category = 'Uncategorized';
  let subcategory = '';

  // Extract content for analysis
  const contentToAnalyze = (bookmark.title + ' ' + (bookmark.excerpt || '')).toLowerCase();
  const domain = extractDomain(bookmark.url);

  // First, check for domain-based categorization
  if (domainCategoryMap[domain]) {
    category = domainCategoryMap[domain];
    subcategory = domain.charAt(0).toUpperCase() + domain.slice(1);
    assigned = true;
  }

  // If not assigned yet, check for common platforms
  if (!assigned) {
    if (bookmark.url.includes('youtube.com') || bookmark.url.includes('youtu.be')) {
      category = 'Entertainment';
      subcategory = 'YouTube';
      assigned = true;
    } else if (bookmark.url.includes('github.com')) {
      category = 'Technology';
      subcategory = 'GitHub';
      assigned = true;
