      category = 'Social Media';
      subcategory = 'Facebook';
      assigned = true;
    } else if (bookmark.url.includes('instagram.com')) {
      category = 'Social Media';
      subcategory = 'Instagram';
      assigned = true;
    } else if (bookmark.url.includes('amazon.com') || bookmark.url.includes('amazon.ca') || bookmark.url.includes('amazon.co.uk')) {
      category = 'Shopping';
      subcategory = 'Amazon';
      assigned = true;
    } else if (bookmark.url.includes('gov.') || bookmark.url.includes('.gov')) {
      category = 'Government & Legal';
      subcategory = domain.charAt(0).toUpperCase() + domain.slice(1);
      assigned = true;
    } else if (bookmark.url.includes('healthline.com') || bookmark.url.includes('webmd.com') || bookmark.url.includes('mayoclinic.org')) {
      category = 'Health';
      subcategory = domain.charAt(0).toUpperCase() + domain.slice(1);
      assigned = true;
    }
  }

  // If still not assigned, use keyword matching
  if (!assigned) {
    for (const [cat, keywords] of Object.entries(categoryKeywords)) {
      for (const keyword of keywords) {
        if (contentToAnalyze.includes(keyword)) {
          category = cat;

          // Try to determine a more specific subcategory
          if (cat === 'Technology') {
            if (contentToAnalyze.includes('programming') || contentToAnalyze.includes('code') || contentToAnalyze.includes('developer')) {
              subcategory = 'Programming';
            } else if (contentToAnalyze.includes('windows') || contentToAnalyze.includes('microsoft')) {
              subcategory = 'Windows';
            } else if (contentToAnalyze.includes('mac') || contentToAnalyze.includes('apple')) {
              subcategory = 'Apple';
            } else if (contentToAnalyze.includes('android')) {
              subcategory = 'Android';
            } else if (contentToAnalyze.includes('network') || contentToAnalyze.includes('wifi') || contentToAnalyze.includes('router')) {
              subcategory = 'Networking';
            } else {
              subcategory = 'General';
            }
          } else if (cat === 'Finance') {
            if (contentToAnalyze.includes('crypto') || contentToAnalyze.includes('bitcoin') || contentToAnalyze.includes('ethereum')) {
              subcategory = 'Cryptocurrency';
            } else if (contentToAnalyze.includes('stock') || contentToAnalyze.includes('invest') || contentToAnalyze.includes('market')) {
              subcategory = 'Investing';
            } else if (contentToAnalyze.includes('trading') || contentToAnalyze.includes('forex')) {
              subcategory = 'Trading';
            } else if (contentToAnalyze.includes('tax') || contentToAnalyze.includes('accounting')) {
              subcategory = 'Taxes & Accounting';
            } else if (contentToAnalyze.includes('bank') || contentToAnalyze.includes('account')) {
              subcategory = 'Banking';
            } else {
              subcategory = 'Personal Finance';
            }
          } else if (cat === 'Health') {
            if (contentToAnalyze.includes('fitness') || contentToAnalyze.includes('workout') || contentToAnalyze.includes('exercise')) {
              subcategory = 'Fitness';
            } else if (contentToAnalyze.includes('diet') || contentToAnalyze.includes('nutrition')) {
              subcategory = 'Nutrition';
            } else if (contentToAnalyze.includes('mental') || contentToAnalyze.includes('therapy') || contentToAnalyze.includes('psychology')) {
              subcategory = 'Mental Health';
            } else if (contentToAnalyze.includes('medical') || contentToAnalyze.includes('doctor') || contentToAnalyze.includes('hospital')) {
              subcategory = 'Medical';
            } else {
              subcategory = 'Wellness';
            }
          } else {
            // For other categories, use domain as subcategory if it's meaningful
            if (domain && domain !== 'other') {
              subcategory = domain.charAt(0).toUpperCase() + domain.slice(1);
            } else {
              subcategory = 'General';
            }
          }

          assigned = true;
          break;
        }
      }
      if (assigned) break;
    }
  }

  // If still not assigned, use domain-based fallback
  if (!assigned) {
    if (domain && domain !== 'other') {
      subcategory = domain.charAt(0).toUpperCase() + domain.slice(1);
    } else {
      subcategory = 'Miscellaneous';
    }
  }

  return {
    ...bookmark,
    category,
    subcategory
  };
});

// Count categories to see distribution
const categoryDistribution = _.countBy(categorizedBookmarks, 'category');
console.log("Category distribution:");
console.log(categoryDistribution);

// Count subcategories within a few main categories to see distribution
const techSubcategories = _.countBy(
  categorizedBookmarks.filter(b => b.category === 'Technology'), 
  'subcategory'
);
console.log("Technology subcategories:");
console.log(techSubcategories);

const financeSubcategories = _.countBy(
  categorizedBookmarks.filter(b => b.category === 'Finance'), 
  'subcategory'
);
console.log("Finance subcategories:");
console.log(financeSubcategories);

// Create a new workbook with categorized data
const newWorkbook = XLSX.utils.book_new();
const newSheet = XLSX.utils.json_to_sheet(categorizedBookmarks);
XLSX.utils.book_append_sheet(newWorkbook, newSheet, 'Categorized_Bookmarks');

// Create a sheet with category summary
const categorySummary = Object.entries(categoryDistribution).map(([category, count]) => ({
  Category: category,
  Count: count,
  Percentage: ((count / categorizedBookmarks.length) * 100).toFixed(2) + '%'
}));
const categorySummarySheet = XLSX.utils.json_to_sheet(categorySummary);
XLSX.utils.book_append_sheet(newWorkbook, categorySummarySheet, 'Category_Summary');

// Convert workbook to binary
const wbout = XLSX.write(newWorkbook, { bookType: 'xlsx', type: 'array' });

// Review a sample of the categorized bookmarks
const categorizedSample = _.sampleSize(categorizedBookmarks, 15);
console.log("Sample of categorized bookmarks:");
console.log(categorizedSample);

