import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Legend } from 'recharts';
import _ from 'lodash';

const COLORS = [
  '#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884D8', 
  '#82CA9D', '#FF6B6B', '#6A7FDB', '#61DAFB', '#FF9F1C',
  '#E63946', '#457B9D', '#1D3557', '#F4A261', '#2A9D8F',
  '#E76F51', '#264653', '#F1FAEE', '#A8DADC

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Legend } from 'recharts';
import _ from 'lodash';

const COLORS = [
  '#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884D8', 
  '#82CA9D', '#FF6B6B', '#6A7FDB', '#61DAFB', '#FF9F1C',
  '#E63946', '#457B9D', '#1D3557', '#F4A261', '#2A9D8F',
  '#E76F51', '#264653', '#F1FAEE', '#A8DADC'
];

const BookmarksSummary = () => {
  const [categoryData, setCategoryData] = useState([]);
  const [subCategoryData, setSubCategoryData] = useState({});
  const [loading, setLoading] = useState(true);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [bookmarkCount, setBookmarkCount] = useState(0);

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        const response = await window.fs.readFile('export.xlsx');

        // Import SheetJS
        const XLSX = await import('xlsx');

        // Parse the Excel file
        const workbook = XLSX.read(response, {cellDates: true});
        const sheet = workbook.Sheets[workbook.SheetNames[0]];
        const bookmarks = XLSX.utils.sheet_to_json(sheet);

        // Remove duplicates
        const uniqueBookmarks = [];
        const seenUrls = new Set();

        bookmarks.forEach(bookmark => {
          if (!seenUrls.has(bookmark.url)) {
            seenUrls.add(bookmark.url);
            uniqueBookmarks.push(bookmark);
          }
        });

        setBookmarkCount(uniqueBookmarks.length);

        // Function to categorize bookmarks
        const categorizedBookmarks = categorizeBooksmarks(uniqueBookmarks);

        // Count categories
        const categoryDistribution = _.countBy(categorizedBookmarks, 'category');

        // Transform for chart
        const categoryChartData = Object.entries(categoryDistribution)
          .map(([name, value]) => ({ name, value }))
          .sort((a, b) => b.value - a.value);

        setCategoryData(categoryChartData);

        // Get subcategories for major categories
        const subCategories = {};
        const mainCategories = _.take(
          _.sortBy(Object.entries(categoryDistribution), ([, count]) => -count)
          .map(([category]) => category), 
          5
        );

        mainCategories.forEach(category => {
          const subcategoryDistribution = _.countBy(
            categorizedBookmarks.filter(b => b.category === category),
            'subcategory'
          );

          subCategories[category] = Object.entries(subcategoryDistribution)
            .map(([name, value]) => ({ name, value }))
            .sort((a, b) => b.value - a.value)
            .slice(0, 10); // Top 10 subcategories
        });

        setSubCategoryData(subCategories);
        setSelectedCategory(mainCategories[0]);
        setLoading(false);
      } catch (error) {
        console.error('Error fetching data:', error);
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  // Function to categorize bookmarks (simplified version)
  const categorizeBooksmarks = (bookmarks) => {
    return bookmarks.map(bookmark => {
      const title = bookmark.title || '';
      const url = bookmark.url || '';

      // Simple categorization based on URL and title
      let category = 'Uncategorized';
      let subcategory = 'General';

      if (url.includes('youtube.com') || url.includes('youtu.be')) {
        category = 'Entertainment';
        subcategory = 'YouTube';
      } else if (url.includes('github.com')) {
        category = 'Technology';
        subcategory = 'GitHub';
      } else if (url.includes('amazon.com')) {
        category = 'Shopping';
        subcategory = 'Amazon';
      } else if (title.toLowerCase().includes('learn') || title.toLowerCase().includes('course')) {
        category = 'Education';
        subcategory = 'Courses';
      } else if (url.includes('google.com')) {
        category = 'Technology';
        subcategory = 'Google';
      } else if (title.toLowerCase().includes('finance') || title.toLowerCase().includes('invest')) {
        category = 'Finance';
        subcategory = 'Investing';
      } else if (url.includes('microsoft') || url.includes('windows')) {
        category = 'Technology';
        subcategory = 'Windows';
      } else if (url.includes('apple.com')) {
        category = 'Technology';
        subcategory = 'Apple';
      }

      return {
        ...bookmark,
        category,
        subcategory
      };
    });
  };

  const handleCategoryClick = (category) => {
    setSelectedCategory(category);
  };

  const renderCustomizedLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, index, name }) => {
    const RADIAN = Math.PI / 180;
    const radius = outerRadius * 1.1;
    const x = cx + radius * Math.cos(-midAngle * RADIAN);
    const y = cy + radius * Math.sin(-midAngle * RADIAN);

    return percent > 0.05 ? (
      <text 
        x={x} 
        y={y} 
        fill={COLORS[index % COLORS.length]} 
        textAnchor={x > cx ? 'start' : 'end'} 
        dominantBaseline="central"
        className="text-xs font-medium"
      >
        {`${name} (${(percent * 100).toFixed(1)}%)`}
      </text>
    ) : null;
  };

  if (loading) {
    return (
      <Card className="w-full p-6">
        <CardContent className="pt-6">
          <div className="flex justify-center items-center h-64">
            <p>Loading bookmark categorization data...</p>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="w-full">
      <CardHeader>
        <CardTitle>Bookmarks Categorization Summary</CardTitle>
        <CardDescription>
          Analysis of {bookmarkCount} unique bookmarks after removing duplicates
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Tabs defaultValue="categories">
          <TabsList className="mb-4">
            <TabsTrigger value="categories">Categories Overview</TabsTrigger>
            <TabsTrigger value="subcategories">Subcategories</TabsTrigger>
          </TabsList>

          <TabsContent value="categories">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
              <Card>
                <CardHeader className="py-2">
                  <CardTitle className="text-lg">Category Distribution</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="h-80">
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie
                          data={categoryData}
                          cx="50%"
                          cy="50%"
                          labelLine={true}
                          label={renderCustomizedLabel}
                          outerRadius={80}
                          fill="#8884d8"
                          dataKey="value"
                        >
                          {categoryData.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                          ))}
                        </Pie>
                        <Tooltip formatter={(value) => [`${value} bookmarks`, null]} />
                      </PieChart>
                    </ResponsiveContainer>
                  </div>
                </CardContent>
              </Card>

              <Card>
                <CardHeader className="py-2">
                  <CardTitle className="text-lg">Top Categories</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="h-80">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart
                        data={categoryData.slice(0, 10)}
                        layout="vertical"
                        margin={{ top: 5, right: 30, left: 80, bottom: 5 }}
                      >
                        <XAxis type="number" />
                        <YAxis type="category" dataKey="name" width={80} />
                        <Tooltip formatter={(value) => [`${value} bookmarks`, null]} />
                        <Bar dataKey="value" fill="#8884d8">
                          {categoryData.slice(0, 10).map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                          ))}
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </CardContent>
              </Card>
            </div>

            <div className="mt-4">
              <h3 className="text-lg font-medium mb-2">Category Statistics</h3>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {categoryData.slice(0, 8).map((category, i) => (
                  <Card key={i} className="cursor-pointer hover:bg-slate-50" onClick={() => handleCategoryClick(category.name)}>
                    <CardContent className="p-4">
                      <div className="flex items-center justify-between">
                        <span className="font-medium">{category.name}</span>
                        <span className="text-sm bg-blue-100 text-blue-800 py-1 px-2 rounded-full">{category.value}</span>
                      </div>
                      <div className="mt-2 text-xs text-gray-500">
                        {((category.value / bookmarkCount) * 100).toFixed(1)}% of total
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            </div>
          </TabsContent>

          <TabsContent value="subcategories">
            <div className="mb-4">
              <div className="flex flex-wrap gap-2 mb-4">
                {Object.keys(subCategoryData).map((category) => (
                  <button
                    key={category}
                    className={`px-3 py-1 rounded text-sm ${selectedCategory === category ? 'bg-blue-500 text-white' : 'bg-gray-200'}`}
                    onClick={() => setSelectedCategory(category)}
                  >
                    {category}
                  </button>
                ))}
              </div>

              {selectedCategory && (
                <Card>
                  <CardHeader className="py-4">
                    <CardTitle className="text-lg">Top Subcategories in {selectedCategory}</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="h-80">
                      <ResponsiveContainer width="100%" height="100%">
                        <BarChart
                          data={subCategoryData[selectedCategory] || []}
                          layout="vertical"
                          margin={{ top: 5, right: 30, left: 100, bottom: 5 }}
                        >
                          <XAxis type="number" />
                          <YAxis type="category" dataKey="name" width={100} />
                          <Tooltip formatter={(value) => [`${value} bookmarks`, null]} />
                          <Bar dataKey="value" fill="#8884d8">
                            {(subCategoryData[selectedCategory] || []).map((entry, index) => (
                              <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                            ))}
                          </Bar>
                        </BarChart>
                      </ResponsiveContainer>
                    </div>
                  </CardContent>
                </Card>
              )}
            </div>
          </TabsContent>
        </Tabs>
      </CardContent>
    </Card>
  );
};

export default BookmarksSummary;

