// Function to extract domain from URL
function extractDomain(url) {
  try {
    const domain = new URL(url).hostname;
    return domain.replace('www.', '').split('.')[0];
  } catch (e) {
    return 'other';
  }
}

// Function to determine category based on title and URL
function determineCategory(bookmark) {
  const title = (bookmark.title || '').toLowerCase();
  const url = (bookmark.url || '').toLowerCase();
  const excerpt = (bookmark.excerpt || '').toLowerCase();
  const contentToAnalyze = title + ' ' + excerpt + ' ' + url;
  const domain = extractDomain(url);

  // Special cases based on URL patterns
  if (url.includes('youtube.com') || url.includes('youtu.be')) {
    return {
      category: "Entertainment & Media",
      subcategory: "YouTube Channels"
    };
  }

  if (url.includes('netflix.com') || url.includes('hulu.com') || url.includes('amazon.com/prime') || url.includes('primevideo') || url.includes('disneyplus') || url.includes('hbomax')) {
    return {
      category: "Entertainment & Media",
      subcategory: "Streaming Services"
    };
  }

  if (url.includes('spotify.com') || url.includes('apple.com/music') || url.includes('soundcloud') || url.includes('podcast')) {
    return {
      category: "Entertainment & Media",
      subcategory: "Music & Podcasts"
    };
  }

  if (url.includes('github.com') || url.includes('stackoverflow.com') || url.includes('developer.') || domain === 'dev') {
    return {
      category: "Technology & Tools",
      subcategory: "Development Tools"
    };
  }

