    return {
      category: "Education & Research",
      subcategory: "Online Courses"
    };
  }

  if (url.includes('canada.ca') || url.includes('gc.ca') || url.includes('gov.') || domain.includes('gov')) {
    return {
      category: "Government & Legal",
      subcategory: "Canadian Services"
    };
  }

  if (url.includes('amazon') || url.includes('ebay') || url.includes('walmart') || url.includes('shop') || url.includes('store')) {
    return {
      category: "Miscellaneous",
      subcategory: "Shopping"
    };
  }

  // Try to match each category based on keywords
  let bestMatch = {
    category: "Miscellaneous",
    subcategory: "General Resources",
    score: 0
  };

  for (const [category, keywords] of Object.entries(categoryKeywords)) {
    let score = 0;

    for (const keyword of keywords) {
      if (contentToAnalyze.includes(keyword)) {
        score += 1;
      }
    }

    if (score > bestMatch.score) {
      bestMatch = {
        category: category,
        subcategory: "", // Will be determined later
        score: score
      };
    }
  }

  // Now determine subcategory for the matched category
  if (bestMatch.category !== "Miscellaneous" || bestMatch.score > 0) {
    const possibleSubcategories = newCategories[bestMatch.category];
    let bestSubcategoryMatch = {
      subcategory: possibleSubcategories[0], // Default to first subcategory
      score: 0
    };

    // Check if we have specific keywords for subcategories
    for (const subcategory of possibleSubcategories) {
      if (subcategoryKeywords[subcategory]) {
        let score = 0;

        for (const keyword of subcategoryKeywords[subcategory]) {
          if (contentToAnalyze.includes(keyword)) {
            score += 1;
          }
        }

        if (score > bestSubcategoryMatch.score) {
          bestSubcategoryMatch = {
            subcategory: subcategory,
            score: score
          };
        }
      }
    }

    // Special case handling for specific categories
    if (bestMatch.category === "Trading & Finance") {
      if (contentToAnalyze.includes("broker") || contentToAnalyze.includes("trading platform") || 
          contentToAnalyze.includes("account") || contentToAnalyze.includes("commission")) {
        bestSubcategoryMatch.subcategory = "Brokerage Platforms";
      } else if (contentToAnalyze.includes("chart") || contentToAnalyze.includes("indicator") || 
                contentToAnalyze.includes("technical") || contentToAnalyze.includes("pattern")) {
        bestSubcategoryMatch.subcategory = "Market Analysis";
      } else if (contentToAnalyze.includes("learn") || contentToAnalyze.includes("course") || 
                contentToAnalyze.includes("tutorial") || contentToAnalyze.includes("guide")) {
        bestSubcategoryMatch.subcategory = "Investment Education";
      }
    } else if (bestMatch.category === "Technology & Tools") {
      if (contentToAnalyze.includes("network") || contentToAnalyze.includes("wifi") || 
          contentToAnalyze.includes("router") || contentToAnalyze.includes("internet")) {
        bestSubcategoryMatch.subcategory = "Networking";
      } else if (contentToAnalyze.includes("security") || contentToAnalyze.includes("protection") || 
                contentToAnalyze.includes("privacy") || contentToAnalyze.includes("vpn")) {
        bestSubcategoryMatch.subcategory = "Cybersecurity";
      }
    }

    bestMatch.subcategory = bestSubcategoryMatch.subcategory;
  }

  return bestMatch;
}

// Apply the new categorization to all bookmarks
