  };
});

// Count categories to see distribution
const categoryDistribution = _.countBy(recategorizedBookmarks, 'category');
console.log("New category distribution:");
console.log(categoryDistribution);

// Count subcategories within each category
const subcategoryDistributions = {};
for (const category of Object.keys(newCategories)) {
  const categoryBookmarks = recategorizedBookmarks.filter(b => b.category === category);
  subcategoryDistributions[category] = _.countBy(categoryBookmarks, 'subcategory');
}

console.log("Subcategory distributions:");
