// Create a new workbook with recategorized data
const newWorkbook = XLSX.utils.book_new();

// Add the main categorized sheet
const categorizedSheet = XLSX.utils.json_to_sheet(recategorizedBookmarks);
XLSX.utils.book_append_sheet(newWorkbook, categorizedSheet, 'All_Categorized');

// Create a sheet for each category
const categoryGroups = _.groupBy(recategorizedBookmarks, 'category');

Object.entries(categoryGroups).forEach(([category, bookmarks]) => {
  // Sort by subcategory
