      category: "Entertainment & Media",
      subcategory: "Music & Podcasts"
    };
  }

  if (url.includes('github.com') || url.includes('stackoverflow.com') || 
      url.includes('developer.') || domain === 'dev' || url.includes('code')) {
    return {
      category: "Technology & Tools",
      subcategory: "Development Tools"
    };
  }

  if (url.includes('udemy.com') || url.includes('coursera.org') || 
      url.includes('edx.org') || url.includes('khan') ||
      url.includes('course') || url.includes('learn')) {
    return {
      category: "Education & Research",
      subcategory: "Online Courses"
    };
  }

  if (url.includes('canada.ca') || url.includes('gc.ca') || 
      url.includes('gov.') || domain.includes('gov')) {
    return {
      category: "Government & Legal",
      subcategory: "Canadian Services"
    };
  }

  if (url.includes('amazon') || url.includes('ebay') || url.includes('walmart') || 
      url.includes('shop') || url.includes('store') || url.includes('buy')) {
    return {
      category: "Miscellaneous",
      subcategory: "Shopping"
    };
  }

  // Check for clear trading/finance content
  if (url.includes('trading') || url.includes('invest') || url.includes('stock') || 
      url.includes('forex') || url.includes('chart') || url.includes('market')) {
    let subcategory = "Market Analysis";

    if (contentToAnalyze.includes('education') || contentToAnalyze.includes('learn') || 
        contentToAnalyze.includes('course') || contentToAnalyze.includes('tutorial')) {
      subcategory = "Investment Education";
    } else if (contentToAnalyze.includes('broker') || contentToAnalyze.includes('platform') || 
               contentToAnalyze.includes('account')) {
      subcategory = "Brokerage Platforms";
    } else if (contentToAnalyze.includes('tool') || contentToAnalyze.includes('calculator') || 
               contentToAnalyze.includes('software')) {
      subcategory = "Financial Tools";
    } else if (contentToAnalyze.includes('economic') || contentToAnalyze.includes('indicator') || 
               contentToAnalyze.includes('report')) {
      subcategory = "Economic Indicators";
    }

    return {
      category: "Trading & Finance",
      subcategory: subcategory
    };
  }

  // Try to match based on keywords
  let bestMatch = {
    category: "Miscellaneous",
    subcategory: "General Resources",
    score: 0
  };

  // Check each category
  for (const [category, keywords] of Object.entries(categoryKeywords)) {
    let score = 0;

    for (const keyword of keywords) {
      if (contentToAnalyze.includes(keyword)) {
        score += 1;
      }
    }

    if (score > bestMatch.score) {
      bestMatch = {
        category: category,
        subcategory: "", // Will determine later
        score: score
      };
    }
  }

  // Now determine subcategory for the matched category
  if (bestMatch.category !== "Miscellaneous" || bestMatch.score > 0) {
    const possibleSubcategories = categories[bestMatch.category];
    let bestSubcategoryMatch = {
      subcategory: possibleSubcategories[0], // Default to first subcategory
      score: 0
    };

    // Check for subcategory keywords
    for (const subcategory of possibleSubcategories) {
      if (subcategoryKeywords[subcategory]) {
        let score = 0;

        for (const keyword of subcategoryKeywords[subcategory]) {
          if (contentToAnalyze.includes(keyword)) {
            score += 1;
          }
        }

        if (score > bestSubcategoryMatch.score) {
          bestSubcategoryMatch = {
            subcategory: subcategory,
            score: score
          };
        }
      }
    }

    bestMatch.subcategory = bestSubcategoryMatch.subcategory;
  }

  return bestMatch;
}

// Apply categorization to bookmarks
const categorizedBookmarks = uniqueBookmarks.map(bookmark => {
  const { category, subcategory } = determineCategory(bookmark);

  return {
    ...bookmark,
    category,
    subcategory
  };
});

// Count categories for verification
const categoryDistribution = _.countBy(categorizedBookmarks, 'category');
console.log("Category distribution:");
console.log(categoryDistribution);

// Sample of categorized bookmarks for verification
console.log("\nSample of categorized bookmarks:");
const categorizedSample = _.sampleSize(categorizedBookmarks, 10);
console.log(categorizedSample);

// Create new workbook with categorized data
const newWorkbook = XLSX.utils.book_new();

// Add the main categorized sheet
const categorizedSheet = XLSX.utils.json_to_sheet(categorizedBookmarks);
XLSX.utils.book_append_sheet(newWorkbook, categorizedSheet, 'All_Categorized');

// Create a sheet for each category
const categoryGroups = _.groupBy(categorizedBookmarks, 'category');

Object.entries(categoryGroups).forEach(([category, bookmarks]) => {
  // Sort by subcategory and title for better organization
  const sortedBookmarks = _.sortBy(bookmarks, ['subcategory', 'title']);

  // Excel sheet names have limitations on characters and length
  const sheetName = category.replace(/[&:\/\\*?"\[\]]/g, '').substring(0, 31);

  const sheet = XLSX.utils.json_to_sheet(sortedBookmarks);
  XLSX.utils.book_append_sheet(newWorkbook, sheet, sheetName);
});

// Create a summary sheet
const categorySummary = Object.entries(categoryDistribution)
  .map(([category, count]) => ({
    Category: category,
    Count: count,
    Percentage: ((count / categorizedBookmarks.length) * 100).toFixed(2) + '%'
  }))
  .sort((a, b) => b.Count - a.Count);

const summarySummarySheet = XLSX.utils.json_to_sheet(categorySummary);
XLSX.utils.book_append_sheet(newWorkbook, summarySummarySheet, 'Category_Summary');

// Add subcategory summaries for each category
Object.entries(categoryGroups).forEach(([category, bookmarks]) => {
  const subcategoryDistribution = _.countBy(bookmarks, 'subcategory');

  const subcategorySummary = Object.entries(subcategoryDistribution)
    .map(([subcategory, count]) => ({
      Subcategory: subcategory,
      Count: count,
      Percentage: ((count / bookmarks.length) * 100).toFixed(2) + '%'
    }))
    .sort((a, b) => b.Count - a.Count);

  const sheetName = (category + '_SubCat').replace(/[&:\/\\*?"\[\]]/g, '').substring(0, 31);
  const sheet = XLSX.utils.json_to_sheet(subcategorySummary);
  XLSX.utils.book_append_sheet(newWorkbook, sheet, sheetName);
});

// Convert workbook to binary for download
const wbout = XLSX.write(newWorkbook, { bookType: 'xlsx', type: 'array' });

// Create CSV data for easy import into Shiori
// Format: URL,Title,Excerpt,Tags
const csvContent = categorizedBookmarks.map(bookmark => {
  const url = bookmark.url || '';
  const title = bookmark.title || '';
  const excerpt = bookmark.excerpt || '';
  const tags = `${bookmark.category},${bookmark.subcategory}`;

  // Escape any commas in fields with quotes
  const escapedTitle = title.includes(',') ? `"${title}"` : title;
  const escapedExcerpt = excerpt.includes(',') ? `"${excerpt}"` : excerpt;

  return `${url},${escapedTitle},${escapedExcerpt},${tags}`;
}).join('\n');

// Add header row
const csvWithHeader = 'URL,Title,Excerpt,Tags\n' + csvContent;

console.log("Categorization complete and CSV prepared for Shiori import");
console.log(csvWithHeader.slice(0, 500) + "..."); // Show a sample of the CSV

